import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'student' }) {
  
  // 1️⃣ Admin Menu Items
  const adminMenuItems = [
    { name: 'Dashboard Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Teacher Feedback', icon: '💬' },
    { name: 'Profile Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items
  const teacherMenuItems = [
    { name: 'Dashboard Overview', icon: '🏠' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Learning Materials', icon: '📂' },
    { name: 'Online Formal Exams', icon: '📝' },
    { name: 'Student Progress', icon: '📈' },
    { name: 'Teacher Feedback', icon: '💬' },
    { name: 'Profile Settings', icon: '⚙️' },
  ];

  // 3️⃣ Student Menu Items (Original Exact Names!)
  const studentMenuItems = [
    { name: 'Dashboard Overview', icon: '🏠' },
    { name: 'Learning Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Online Formal Exams', icon: '📝' },
    { name: 'Teacher Feedback', icon: '💬' },
    { name: 'Profile Settings', icon: '⚙️' },
  ];

  // 🔄 Role අනුව Menu Select කිරීම
  let menuItems = studentMenuItems;
  if (role === 'admin') menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;

  return (
    <aside style={styles.sidebar}>
      
      {/* 🟢 Header Title Section */}
      <div style={styles.brandContainer}>
        <h2 style={styles.brandTitle}>Aura Pen Saku</h2>
        <span style={styles.roleSubtext}>{role.toUpperCase()} PORTAL</span>
      </div>

      {/* 🟢 Nav Menu Section */}
      <div style={styles.menuList}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                ...styles.navButton,
                // Active වෙන item එකට ලස්සන Light Transparent Box එක
                backgroundColor: isActive ? 'rgba(255, 255, 255, 0.22)' : 'transparent',
                fontWeight: isActive ? 'bold' : '500',
              }}
            >
              <span style={{ fontSize: '18px' }}>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          );
        })}
      </div>

      {/* 🔴 Logout Button */}
      <div style={styles.logoutContainer}>
        <button onClick={onLogoutClick} style={styles.logoutBtn}>
          Logout Terminal 🚪
        </button>
      </div>

    </aside>
  );
}

const styles = {
  sidebar: {
    width: '260px',
    minWidth: '260px',
    height: 'calc(100vh - 90px)',
    backgroundColor: '#0d5c2e', // Original Pure Green
    color: '#ffffff',
    display: 'flex',
    flexDirection: 'column',
    padding: '20px 14px',
    boxSizing: 'border-box',
  },
  brandContainer: {
    paddingBottom: '14px',
    marginBottom: '10px',
    borderBottom: '1px solid rgba(255, 255, 255, 0.15)',
  },
  brandTitle: {
    margin: 0,
    fontSize: '21px',
    fontWeight: '800',
    color: '#ffffff',
    letterSpacing: '0.3px',
  },
  roleSubtext: {
    fontSize: '11px',
    fontWeight: '700',
    color: '#bbf7d0',
    letterSpacing: '0.8px',
    display: 'block',
    marginTop: '3px',
  },
  menuList: {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
    overflowY: 'auto',
  },
  navButton: {
    width: '100%',
    textAlign: 'left',
    padding: '12px 14px',
    border: 'none',
    borderRadius: '12px',
    color: '#ffffff',
    cursor: 'pointer',
    fontSize: '14.5px',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: 'all 0.15s ease',
  },
  logoutContainer: {
    paddingTop: '12px',
    marginTop: 'auto',
    borderTop: '1px solid rgba(255, 255, 255, 0.15)',
  },
  logoutBtn: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#dc2626',
    color: '#ffffff',
    border: 'none',
    borderRadius: '12px',
    fontWeight: 'bold',
    fontSize: '14.5px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    boxShadow: '0 4px 10px rgba(0, 0, 0, 0.15)',
  }
};
